const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const AutoHashMap = std.AutoHashMap;
const StringHashMap = std.StringHashMap;
const Complex = std.math.Complex;

const nsir = @import("nsircore.zig");
const SelfSimilarRelationalGraph = nsir.SelfSimilarRelationalGraph;
const Node = nsir.Node;
const Edge = nsir.Edge;
const EdgeQuality = nsir.EdgeQuality;
const EdgeKey = nsir.EdgeKey;

const orchestrator = @import("reasoning_orchestrator.zig");
const ReasoningOrchestrator = orchestrator.ReasoningOrchestrator;
const ThoughtLevel = orchestrator.ThoughtLevel;

const memory = @import("memory.zig");
const MemoryArena = memory.Arena;

pub const TaskDomain = enum {
    analytical,
    creative,
    interactive,
    social,
    spatial,
    unknown,
};

pub const TaskFeatures = struct {
    complexity: f64,
    ambiguity: f64,
    urgency: f64,
    emotional_load: f64,
};

pub const CapabilityInput = struct {
    task_id_hash: u64,
    domain: TaskDomain,
    features: TaskFeatures,
    timestamp: i64,
};

pub const ExperienceSummary = struct {
    task_hash: u64,
    domain: TaskDomain,
    features: TaskFeatures,
    novelty_score: f64,
    success_rate: f64,
    convergence_energy: f64,
    cycles_taken: usize,
};

pub const SocialInferenceModel = struct {
    intent_clarity: f64,
    user_frustration: f64,
    requires_empathy: bool,
    expected_response_depth: usize,

    pub fn init() SocialInferenceModel {
        return .{
            .intent_clarity = 0.5,
            .user_frustration = 0.0,
            .requires_empathy = false,
            .expected_response_depth = 3,
        };
    }
};

pub const AdaptiveCapabilityLayer = struct {
    graph: *SelfSimilarRelationalGraph,
    reasoning_orchestrator: *ReasoningOrchestrator,
    memory_arena: MemoryArena,
    experience_buffer: ArrayList(ExperienceSummary),
    social_model: SocialInferenceModel,
    allocator: Allocator,

    const Self = @This();

    pub fn init(
        allocator: Allocator, 
        graph: *SelfSimilarRelationalGraph, 
        reasoning_orch: *ReasoningOrchestrator
    ) !Self {
        var arena = try MemoryArena.init(allocator, 1024 * 1024);

        return Self{
            .graph = graph,
            .reasoning_orchestrator = reasoning_orch,
            .memory_arena = arena,
            .experience_buffer = ArrayList(ExperienceSummary).init(allocator),
            .social_model = SocialInferenceModel.init(),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Self) void {
        self.experience_buffer.deinit();
        self.memory_arena.deinit();
    }

    pub fn classifyTask(self: *Self, input: CapabilityInput) TaskDomain {
        _ = self;
        if (input.features.emotional_load > 0.7) return .social;
        if (input.features.complexity > 0.8 and input.features.ambiguity < 0.3) return .analytical;
        if (input.features.ambiguity > 0.7) return .creative;
        return input.domain;
    }

    pub fn scoreNoveltyAndTransferability(self: *Self, input: CapabilityInput) struct { novelty: f64, transferability: f64 } {
        if (self.experience_buffer.items.len == 0) {
            return .{ .novelty = 1.0, .transferability = 0.0 };
        }

        var min_dist: f64 = std.math.inf(f64);
        var best_match_success: f64 = 0.0;

        for (self.experience_buffer.items) |exp| {
            if (exp.domain != input.domain) continue;

            const dc = exp.features.complexity - input.features.complexity;
            const da = exp.features.ambiguity - input.features.ambiguity;
            const dist = std.math.sqrt(dc * dc + da * da);

            if (dist < min_dist) {
                min_dist = dist;
                best_match_success = exp.success_rate;
            }
        }

        if (std.math.isInf(min_dist)) {
            return .{ .novelty = 1.0, .transferability = 0.0 };
        }

        const novelty = std.math.clamp(min_dist, 0.0, 1.0);
        const transferability = (1.0 - novelty) * best_match_success;

        return .{ .novelty = novelty, .transferability = transferability };
    }

    pub fn adjustReasoningPolicy(self: *Self, novelty: f64, transferability: f64, domain: TaskDomain) void {
        var inner: usize = 50;
        var outer: usize = 10;
        var depth: usize = 3;

        if (novelty > 0.8 and transferability < 0.2) {
            inner = 100;
            outer = 20;
            depth = 5;
        } else if (transferability > 0.8) {
            inner = 20;
            outer = 5;
            depth = 2;
        }

        if (domain == .social or domain == .creative) {
            outer += 10;
        } else if (domain == .analytical) {
            inner += 50;
        }

        self.reasoning_orchestrator.setParameters(inner, outer, depth);

        const perturb = if (novelty > 0.5) @as(usize, 20) else @as(usize, 5);
        self.reasoning_orchestrator.setProcessingLimits(perturb, perturb, perturb / 2);
    }

    pub fn process(self: *Self, input: CapabilityInput) !f64 {
        const resolved_domain = self.classifyTask(input);

        self.social_model.requires_empathy = (resolved_domain == .social or input.features.emotional_load > 0.6);
        self.social_model.user_frustration = if (input.features.urgency > 0.8) 0.5 else 0.0;

        const scores = self.scoreNoveltyAndTransferability(input);

        self.adjustReasoningPolicy(scores.novelty, scores.transferability, resolved_domain);

        const max_cycles = if (scores.novelty > 0.7) @as(usize, 10) else @as(usize, 3);
        const final_energy = try self.reasoning_orchestrator.runHierarchicalReasoning(max_cycles);

        const success = if (final_energy < 0.1) @as(f64, 1.0) else (1.0 / (1.0 + final_energy));

        try self.onlineConsolidate(ExperienceSummary{
            .task_hash = input.task_id_hash,
            .domain = resolved_domain,
            .features = input.features,
            .novelty_score = scores.novelty,
            .success_rate = success,
            .convergence_energy = final_energy,
            .cycles_taken = max_cycles,
        });

        return final_energy;
    }

    fn onlineConsolidate(self: *Self, summary: ExperienceSummary) !void {
        if (self.experience_buffer.items.len > 1000) {
            _ = self.experience_buffer.orderedRemove(0);
        }
        try self.experience_buffer.append(summary);
    }
};

