```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const AutoHashMap = std.AutoHashMap;
const Mutex = std.Thread.Mutex;

const nsircore = @import("../nsircore.zig");
const SelfSimilarRelationalGraph = nsircore.SelfSimilarRelationalGraph;
const Node = nsircore.Node;
const Edge = nsircore.Edge;
const EdgeKey = nsircore.EdgeKey;
const Qubit = nsircore.Qubit;

pub const TaskClassification = enum(u8) {
    analytical = 0,
    creative = 1,
    interactive = 2,
    recovery = 3,
    social_inference = 4,
    unknown = 5,
};

pub const TaskFeatures = struct {
    complexity: f32,
    ambiguity: f32,
    urgency: f32,
    emotional_load: f32,
};

pub const CapabilityInput = struct {
    task_hash: u64,
    domain_label: []const u8,
    features: TaskFeatures,
    user_intent_score: f32,
    timestamp: i64,
};

pub const ExperienceSummary = struct {
    task_hash: u64,
    classification: TaskClassification,
    features: TaskFeatures,
    novelty_score: f32,
    success_rate: f32,
    convergence_energy: f32,
    fast_inner_steps_used: usize,
    slow_outer_steps_used: usize,
    timestamp: i64,
};

pub const SocialInferenceModel = struct {
    mutex: Mutex,
    user_intent_certainty: f32,
    urgency_level: f32,
    frustration_index: f32,
    cognitive_load_estimate: f32,
    expected_response_depth: usize,

    pub fn init() SocialInferenceModel {
        return .{
            .mutex = Mutex{},
            .user_intent_certainty = 0.5,
            .urgency_level = 0.5,
            .frustration_index = 0.0,
            .cognitive_load_estimate = 0.5,
            .expected_response_depth = 5,
        };
    }

    pub fn update(self: *SocialInferenceModel, intent_score: f32, latency_ms: f32, urgency: f32, emotional_load: f32) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.user_intent_certainty = (self.user_intent_certainty * 0.8) + (intent_score * 0.2);
        self.urgency_level = (self.urgency_level * 0.7) + (urgency * 0.3);
        self.cognitive_load_estimate = (self.cognitive_load_estimate * 0.9) + (emotional_load * 0.1);
        const frust_delta = if (latency_ms > 2000.0) @as(f32, 0.1) else if (latency_ms < 500.0) @as(f32, -0.05) else @as(f32, 0.0);
        self.frustration_index = std.math.clamp(self.frustration_index + frust_delta + (urgency * 0.05), 0.0, 1.0);
        self.expected_response_depth = @as(usize, @intFromFloat(self.cognitive_load_estimate * 10.0)) + 1;
    }
};

pub const ExperienceBuffer = struct {
    allocator: Allocator,
    experiences: []ExperienceSummary,
    lookup: AutoHashMap(u64, usize),
    head: usize,
    count: usize,
    capacity: usize,
    mutex: Mutex,

    pub fn init(allocator: Allocator, capacity: usize) !ExperienceBuffer {
        return ExperienceBuffer{
            .allocator = allocator,
            .experiences = try allocator.alloc(ExperienceSummary, capacity),
            .lookup = AutoHashMap(u64, usize).init(allocator),
            .head = 0,
            .count = 0,
            .capacity = capacity,
            .mutex = Mutex{},
        };
    }

    pub fn deinit(self: *ExperienceBuffer) void {
        self.lookup.deinit();
        self.allocator.free(self.experiences);
    }

    pub fn addExperience(self: *ExperienceBuffer, exp: ExperienceSummary) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.count == self.capacity) {
            const old_hash = self.experiences[self.head].task_hash;
            _ = self.lookup.remove(old_hash);
        } else {
            self.count += 1;
        }
        self.experiences[self.head] = exp;
        try self.lookup.put(exp.task_hash, self.head);
        self.head = (self.head + 1) % self.capacity;
    }

    pub fn retrieveRelevant(self: *ExperienceBuffer, input: CapabilityInput) ?ExperienceSummary {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.lookup.get(input.task_hash)) |idx| {
            return self.experiences[idx];
        }
        var best_match: ?ExperienceSummary = null;
        var min_dist: f32 = std.math.floatMax(f32);
        const now = std.time.nanoTimestamp();
        var i: usize = 0;
        while (i < self.count) : (i += 1) {
            const exp = self.experiences[i];
            const age_ns = now - exp.timestamp;
            const age_penalty = if (age_ns > 0) @as(f32, @floatFromInt(age_ns)) / 1000000000000.0 else 0.0;
            const d_comp = exp.features.complexity - input.features.complexity;
            const d_amb = exp.features.ambiguity - input.features.ambiguity;
            const d_urg = exp.features.urgency - input.features.urgency;
            const d_emo = exp.features.emotional_load - input.features.emotional_load;
            const dist = @sqrt(d_comp * d_comp + d_amb * d_amb + d_urg * d_urg + d_emo * d_emo) + (age_penalty * 0.01);
            if (dist < min_dist) {
                min_dist = dist;
                best_match = exp;
            }
        }
        return best_match;
    }
};

