    slow_outer_steps_used: usize,
    timestamp: i64,
};

pub const SocialConfig = struct {
    high_latency: f64,
    low_latency: f64,
};

pub const SocialInferenceModel = struct {
    mutex: std.Thread.Mutex,
    user_intent_certainty: f64,
    urgency_level: f64,
    frustration_index: f64,
    cognitive_load_estimate: f64,
    expected_response_depth: usize,
    config: SocialConfig,

    pub fn init(config: SocialConfig) SocialInferenceModel {
        return .{
            .mutex = std.Thread.Mutex{},
            .user_intent_certainty = 0.5,
            .urgency_level = 0.5,
            .frustration_index = 0.0,
            .cognitive_load_estimate = 0.5,
            .expected_response_depth = 5,
            .config = config,
        };
    }

    pub fn update(self: *SocialInferenceModel, intent_score: f64, latency_ms: f64, urgency: f64, emotional_load: f64) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.user_intent_certainty = (self.user_intent_certainty * 0.8) + (intent_score * 0.2);
        self.urgency_level = (self.urgency_level * 0.7) + (urgency * 0.3);
        self.cognitive_load_estimate = (self.cognitive_load_estimate * 0.9) + (emotional_load * 0.1);
        const frust_delta = if (latency_ms > self.config.high_latency) @as(f64, 0.1) else if (latency_ms < self.config.low_latency) @as(f64, -0.05) else @as(f64, 0.0);
        const temp_frust = self.frustration_index + frust_delta + (urgency * 0.05);
        self.frustration_index = std.math.clamp(temp_frust, 0.0, 1.0);
        const clamped_load = std.math.clamp(self.cognitive_load_estimate, 0.0, 1.0);
        self.expected_response_depth = @as(usize, @intFromFloat(std.math.round(clamped_load * 10.0))) + 1;
    }

    pub fn getExpectedDepth(self: *SocialInferenceModel) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.expected_response_depth;
    }
};

pub const ExperienceBuffer = struct {
    allocator: std.mem.Allocator,
    experiences: std.ArrayList(ExperienceSummary),
    lookup: std.AutoHashMap(u64, usize),
    mutex: std.Thread.Mutex,

    pub fn init(allocator: std.mem.Allocator) !ExperienceBuffer {
        return ExperienceBuffer{
            .allocator = allocator,
            .experiences = std.ArrayList(ExperienceSummary).init(allocator),
            .lookup = std.AutoHashMap(u64, usize).init(allocator),
            .mutex = std.Thread.Mutex{},
        };
    }

    pub fn deinit(self: *ExperienceBuffer) void {
        self.lookup.deinit();
        self.experiences.deinit();
    }

    pub fn addExperience(self: *ExperienceBuffer, exp: ExperienceSummary) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.lookup.get(exp.task_hash)) |idx| {
            self.experiences.items[idx] = exp;
        } else {
            const idx = self.experiences.items.len;
            try self.experiences.append(exp);
            try self.lookup.put(exp.task_hash, idx);
        }
    }

    pub fn retrieveRelevant(self: *ExperienceBuffer, input: CapabilityInput) ?ExperienceSummary {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.lookup.get(input.task_hash)) |idx| {
            return self.experiences.items[idx];
        }
        var best_match: ?ExperienceSummary = null;
        var min_dist: f64 = std.math.floatMax(f64);
        const now = std.time.nanoTimestamp();
        for (self.experiences.items) |exp| {
            const age_ns = now - exp.timestamp;
            const age_s = @divTrunc(age_ns, 1000000000);
            const age_penalty = @max(0.0, @as(f64, @floatFromInt(age_s)) * 0.0001);
            const d_comp = exp.features.complexity - input.features.complexity;
            const d_amb = exp.features.ambiguity - input.features.ambiguity;
            const d_urg = exp.features.urgency - input.features.urgency;
            const d_emo = exp.features.emotional_load - input.features.emotional_load;
            const dist = std.math.sqrt(d_comp * d_comp + d_amb * d_amb + d_urg * d_urg + d_emo * d_emo) + age_penalty;
            if (dist < min_dist) {
                min_dist = dist;
                best_match = exp;
            }
        }
        return best_match;
    }
};

