        }
        const base_cycles: u64 = @as(u64, final_fast) + (@as(u64, final_slow) * 10);
        const urgency_factor = std.math.clamp(1.0 + input.features.urgency + input.features.emotional_load, 1.0, 3.0);
        const max_cycles = @as(u64, @intFromFloat(@as(f64, @floatFromInt(base_cycles)) * urgency_factor));
        const expected_energy = @as(f64, @floatFromInt(final_fast)) * 0.1 + @as(f64, @floatFromInt(final_slow)) * 0.5 + (self.config.perturb_base * novelty);
        return .{
            .fast_steps = final_fast,
            .slow_steps = final_slow,
            .max_cycles = max_cycles,
            .expected_energy = expected_energy,
            .novelty = novelty,
        };
    }

    pub fn process(self: *AdaptiveCapabilityLayer, input: CapabilityInput) !ProcessResult {
        const classification = self.classifyTask(input);
        const metrics = self.scoreNoveltyAndTransferability(input, classification);
        self.social_model.update(input.user_intent_score, input.latency_ms, input.features.urgency, input.features.emotional_load);
        return self.adjustReasoningPolicy(classification, metrics.novelty, metrics.transferability, input);
    }

    pub fn onlineConsolidate(self: *AdaptiveCapabilityLayer, input: CapabilityInput, classification: TaskClassification, final_energy: f64, used_fast: usize, used_slow: usize, computed_novelty: f64) !void {
        const success_rate = std.math.clamp(1.0 / (1.0 + @max(0.0, final_energy)), 0.0, 1.0);
        const exp = ExperienceSummary{
            .task_hash = input.task_hash,
            .classification = classification,
            .features = input.features,
            .novelty_score = computed_novelty,
            .success_rate = success_rate,
            .convergence_energy = final_energy,
            .fast_inner_steps_used = used_fast,
            .slow_outer_steps_used = used_slow,
            .timestamp = input.timestamp,
        };
        try self.experience_buffer.addExperience(exp);
        const class_idx = @intFromEnum(classification);
        if (class_idx < @typeInfo(TaskClassification).Enum.fields.len) {
            if (success_rate > 0.8) {
                self.strategy_weights[class_idx] = std.math.clamp(self.strategy_weights[class_idx] * 1.05, 0.1, 5.0);
            } else if (success_rate < 0.4) {
                self.strategy_weights[class_idx] = std.math.clamp(self.strategy_weights[class_idx] * 0.95, 0.1, 5.0);
            }
        }
    }
};

