pub const SocialSnapshot = struct {
    intent_clarity: f64,
    user_frustration: f64,
    requires_empathy: bool,
    expected_response_depth: usize,
};

pub const SocialInferenceModel = struct {
    mutex: std.Thread.Mutex,
    intent_clarity: f64,
    user_frustration: f64,
    requires_empathy: bool,
    expected_response_depth: usize,
    config: SocialConfig,

    pub fn init(config: SocialConfig) SocialInferenceModel {
        const validated = config.validated();
        return .{
            .mutex = .{},
            .intent_clarity = 0.5,
            .user_frustration = 0.0,
            .requires_empathy = false,
            .expected_response_depth = validated.depth_min,
            .config = validated,
        };
    }

    pub fn update(self: *SocialInferenceModel, domain: TaskDomain, features: TaskFeatures) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        const clarity_signal = 1.0 - std.math.clamp(features.ambiguity, 0.0, 1.0);
        self.intent_clarity = std.math.clamp((self.intent_clarity * self.config.intent_decay) + (clarity_signal * (1.0 - self.config.intent_decay)), 0.0, 1.0);

        const frustration_signal = (std.math.clamp(features.urgency, 0.0, 1.0) * self.config.frustration_urgency_scale) + (std.math.clamp(features.emotional_load, 0.0, 1.0) * self.config.frustration_emotional_scale);
        self.user_frustration = std.math.clamp((self.user_frustration * self.config.frustration_decay) + frustration_signal, 0.0, 1.0);

        self.requires_empathy = domain == .social or features.emotional_load >= self.config.empathy_emotional_threshold;

        const depth_signal = std.math.clamp((features.complexity * 0.45) + (features.ambiguity * 0.25) + (features.emotional_load * 0.15) + (if (self.requires_empathy) 0.15 else 0.0), 0.0, 1.0);
        const depth_span = self.config.depth_max - self.config.depth_min;
        const computed_depth = self.config.depth_min + @as(usize, @intFromFloat(std.math.round(depth_signal * @as(f64, @floatFromInt(depth_span)))));
        self.expected_response_depth = std.math.clamp(computed_depth, self.config.depth_min, self.config.depth_max);
    }

    pub fn snapshot(self: *SocialInferenceModel) SocialSnapshot {
        self.mutex.lock();
        defer self.mutex.unlock();
        return .{
            .intent_clarity = self.intent_clarity,
            .user_frustration = self.user_frustration,
            .requires_empathy = self.requires_empathy,
            .expected_response_depth = self.expected_response_depth,
        };
    }
};

const DomainBucket = struct {
    indices: []usize,
    len: usize,

    fn init(allocator: Allocator, capacity: usize) !DomainBucket {
        return .{
            .indices = try allocator.alloc(usize, capacity),
            .len = 0,
        };
    }

    fn deinit(self: *DomainBucket, allocator: Allocator) void {
        allocator.free(self.indices);
        self.indices = &[_]usize{};
        self.len = 0;
    }

    fn add(self: *DomainBucket, index: usize) !void {
        if (self.len >= self.indices.len) return error.DomainBucketFull;
        self.indices[self.len] = index;
        self.len += 1;
    }

    fn addAssumeCapacity(self: *DomainBucket, index: usize) void {
        self.indices[self.len] = index;
        self.len += 1;
    }

    fn remove(self: *DomainBucket, index: usize) bool {
        var i: usize = 0;
        while (i < self.len) : (i += 1) {
            if (self.indices[i] == index) {
                self.len -= 1;
                self.indices[i] = self.indices[self.len];
                return true;
            }
        }
        return false;
    }
};

pub const ExperienceBuffer = struct {
    allocator: Allocator,
    slots: []ExperienceSummary,
    active: []bool,
    len: usize,
    next_evict: usize,
    capacity: usize,
    exact_index: AutoHashMap(u64, usize),
    domain_buckets: [TaskDomainCount]DomainBucket,
    mutex: std.Thread.Mutex,

    pub fn init(allocator: Allocator, capacity: usize) !ExperienceBuffer {
        if (capacity == 0) return error.InvalidCapacity;

        var exact_index = AutoHashMap(u64, usize).init(allocator);
        errdefer exact_index.deinit();
        try exact_index.ensureTotalCapacity(capacity);

        var domain_buckets: [TaskDomainCount]DomainBucket = undefined;
        var initialized_buckets: usize = 0;
        errdefer {
            var i: usize = 0;
            while (i < initialized_buckets) : (i += 1) {
                domain_buckets[i].deinit(allocator);
            }
        }

        var i: usize = 0;
        while (i < TaskDomainCount) : (i += 1) {
            domain_buckets[i] = try DomainBucket.init(allocator, capacity);
            initialized_buckets += 1;
        }

        const slots = try allocator.alloc(ExperienceSummary, capacity);
        errdefer allocator.free(slots);

        const active = try allocator.alloc(bool, capacity);
        errdefer allocator.free(active);
        @memset(active, false);

        return .{
            .allocator = allocator,
            .slots = slots,
            .active = active,
            .len = 0,
            .next_evict = 0,
            .capacity = capacity,
            .exact_index = exact_index,
            .domain_buckets = domain_buckets,
            .mutex = .{},
        };
    }

    pub fn deinit(self: *ExperienceBuffer) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        self.exact_index.deinit();

        var i: usize = 0;
        while (i < TaskDomainCount) : (i += 1) {
            self.domain_buckets[i].deinit(self.allocator);
        }

        self.allocator.free(self.active);
        self.allocator.free(self.slots);

        self.active = &[_]bool{};
        self.slots = &[_]ExperienceSummary{};
        self.len = 0;
        self.next_evict = 0;
        self.capacity = 0;
    }

    pub fn count(self: *ExperienceBuffer) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.len;
    }

    pub fn addExperience(self: *ExperienceBuffer, exp: ExperienceSummary) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.exact_index.get(exp.task_hash)) |existing_index| {
            const old_domain = self.slots[existing_index].domain;
            self.slots[existing_index] = exp;
            if (old_domain != exp.domain) {
                _ = self.domain_buckets[@intFromEnum(old_domain)].remove(existing_index);
                try self.domain_buckets[@intFromEnum(exp.domain)].add(existing_index);
            }
            self.active[existing_index] = true;
            return;
        }

        if (self.len < self.capacity) {
            const insert_index = self.len;
            try self.exact_index.put(exp.task_hash, insert_index);
            errdefer _ = self.exact_index.remove(exp.task_hash);

            self.slots[insert_index] = exp;
            self.active[insert_index] = true;
            self.len += 1;
            errdefer {
                self.active[insert_index] = false;
                self.len -= 1;
            }

            try self.domain_buckets[@intFromEnum(exp.domain)].add(insert_index);
            return;
        }

        const replace_index = self.next_evict;
        const had_old = self.active[replace_index];
        const old_exp = if (had_old) self.slots[replace_index] else undefined;

        if (had_old) {
            _ = self.exact_index.remove(old_exp.task_hash);
            _ = self.domain_buckets[@intFromEnum(old_exp.domain)].remove(replace_index);
        }

        errdefer {
            if (had_old) {
                self.slots[replace_index] = old_exp;
                self.active[replace_index] = true;
                self.exact_index.put(old_exp.task_hash, replace_index) catch unreachable;
                self.domain_buckets[@intFromEnum(old_exp.domain)].addAssumeCapacity(replace_index);
            } else {
                self.active[replace_index] = false;
            }
        }

        try self.exact_index.put(exp.task_hash, replace_index);
        self.slots[replace_index] = exp;
        self.active[replace_index] = true;
        try self.domain_buckets[@intFromEnum(exp.domain)].add(replace_index);

        self.next_evict = (replace_index + 1) % self.capacity;
    }

    pub fn retrieveRelevant(self: *ExperienceBuffer, task_hash: u64, domain: TaskDomain, features: TaskFeatures, timestamp: i64, scales: FeatureScales, age_penalty_scale: f64) ?ExperienceSummary {
        const now = timestamp;

        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.exact_index.get(task_hash)) |exact_index| {
            if (self.active[exact_index]) {
                return self.slots[exact_index];
            }
        }

        var best_match: ?ExperienceSummary = null;
        var min_distance = std.math.floatMax(f64);

        if (domain == .unknown) {
            var i: usize = 0;
            while (i < self.len) : (i += 1) {
                if (!self.active[i]) continue;
                const exp = self.slots[i];
                const distance = featureDistance(exp.features, features, scales) + agePenalty(now, exp.timestamp, age_penalty_scale);
                if (distance < min_distance) {
                    min_distance = distance;
                    best_match = exp;
                }
            }
            return best_match;
        }

        const bucket = self.domain_buckets[@intFromEnum(domain)];
        var i: usize = 0;
        while (i < bucket.len) : (i += 1) {
            const slot_index = bucket.indices[i];
            if (!self.active[slot_index]) continue;
            const exp = self.slots[slot_index];
            const distance = featureDistance(exp.features, features, scales) + agePenalty(now, exp.timestamp, age_penalty_scale);
            if (distance < min_distance) {
                min_distance = distance;
                best_match = exp;
            }
        }

        return best_match;
    }

    fn featureDistance(a: TaskFeatures, b: TaskFeatures, scales: FeatureScales) f64 {
        const dc = (a.complexity - b.complexity) / scales.complexity;
        const da = (a.ambiguity - b.ambiguity) / scales.ambiguity;
        const du = (a.urgency - b.urgency) / scales.urgency;
        const de = (a.emotional_load - b.emotional_load) / scales.emotional_load;
        const sum = (dc * dc) + (da * da) + (du * du) + (de * de);
        return std.math.clamp(std.math.sqrt(sum / 4.0), 0.0, 1.0);
    }

    fn agePenalty(now: i64, then: i64, scale: f64) f64 {
        const delta_ns = now - then;
        if (delta_ns <= 0) return 0.0;
        const delta_s = @as(f64, @floatFromInt(delta_ns)) / 1_000_000_000.0;
        return @max(0.0, delta_s * scale);
    }
};

pub const AdaptiveCapabilityLayer = struct {
    graph: *SelfSimilarRelationalGraph,
    reasoning_orchestrator: *ReasoningOrchestrator,
    experience_buffer: ExperienceBuffer,
    social_model: SocialInferenceModel,
    config: AdaptiveCapabilityConfig,

    const Self = @This();

    pub fn init(allocator: Allocator, graph: *SelfSimilarRelationalGraph, reasoning_orch: *ReasoningOrchestrator) !Self {
        return Self.initWithConfig(allocator, graph, reasoning_orch, .{});
    }

    pub fn initWithConfig(allocator: Allocator, graph: *SelfSimilarRelationalGraph, reasoning_orch: *ReasoningOrchestrator, config: AdaptiveCapabilityConfig) !Self {
        const validated_config = config.validated();
        return .{
            .graph = graph,
            .reasoning_orchestrator = reasoning_orch,
            .experience_buffer = try ExperienceBuffer.init(allocator, validated_config.experience_capacity),
            .social_model = SocialInferenceModel.init(validated_config.social),
            .config = validated_config,
        };
    }

    pub fn deinit(self: *Self) void {
        self.experience_buffer.deinit();
    }

    pub fn classifyTask(self: *Self, input: CapabilityInput) TaskDomain {
        if (input.domain != .unknown) return input.domain;
        if (input.features.emotional_load >= self.config.social_emotional_threshold) return .social;
        if (input.features.complexity >= self.config.analytical_complexity_threshold and input.features.ambiguity <= self.config.analytical_ambiguity_threshold) return .analytical;
        if (input.features.ambiguity >= self.config.creative_ambiguity_threshold) return .creative;
        if (input.features.urgency >= self.config.interactive_urgency_threshold) return .interactive;
        if (input.features.complexity >= 0.50 and input.features.ambiguity < 0.50) return .analytical;
        return .interactive;
    }

    pub fn scoreNoveltyAndTransferability(self: *Self, input: CapabilityInput, resolved_domain: TaskDomain) struct { novelty: f64, transferability: f64 } {
        const prior = self.experience_buffer.retrieveRelevant(input.task_id_hash, resolved_domain, input.features, input.timestamp, self.config.feature_scales, self.config.age_penalty_scale);

        if (prior == null) {
            return .{ .novelty = 1.0, .transferability = 0.0 };
        }

        const exp = prior.?;
        const novelty = std.math.clamp(ExperienceBuffer.featureDistance(exp.features, input.features, self.config.feature_scales) + ExperienceBuffer.agePenalty(input.timestamp, exp.timestamp, self.config.age_penalty_scale), 0.0, 1.0);
        const success_component = std.math.clamp(exp.success_rate, 0.0, 1.0);
        const energy_component = 1.0 - std.math.clamp(exp.convergence_energy, 0.0, 1.0);
        const transferability = std.math.clamp((1.0 - novelty) * ((success_component * 0.7) + (energy_component * 0.3)), 0.0, 1.0);

        return .{
            .novelty = novelty,
            .transferability = transferability,
        };
    }

    pub fn adjustReasoningPolicy(self: *Self, novelty: f64, transferability: f64, domain: TaskDomain, social: SocialSnapshot) void {
        var inner = self.config.base_inner_steps;
        var outer = self.config.base_outer_steps;
        var depth = self.config.base_depth;

        if (novelty >= self.config.novelty_high_threshold and transferability < (1.0 - self.config.transfer_high_threshold)) {
            inner = self.config.novel_inner_steps;
            outer = self.config.novel_outer_steps;
            depth = self.config.novel_depth;
        } else if (transferability >= self.config.transfer_high_threshold) {
            inner = self.config.familiar_inner_steps;
            outer = self.config.familiar_outer_steps;
            depth = self.config.familiar_depth;
        }

        switch (domain) {
            .social => {
                outer = saturatingAdd(outer, self.config.social_outer_bonus);
                depth = @max(depth, social.expected_response_depth);
            },
            .creative => {
                outer = saturatingAdd(outer, self.config.creative_outer_bonus);
                depth = @max(depth, social.expected_response_depth);
            },
            .analytical => {
                inner = saturatingAdd(inner, self.config.analytical_inner_bonus);
            },
            .interactive => {
                depth = @max(depth, social.expected_response_depth);
            },
            .spatial => {
                depth = @max(depth, social.expected_response_depth);
            },
            .unknown => {
                outer = saturatingAdd(outer, self.config.unknown_outer_bonus);
            },
        }

        depth = @max(depth, social.expected_response_depth);

        self.reasoning_orchestrator.setParameters(
            @max(@as(usize, 1), inner),
            @max(@as(usize, 1), outer),
            @max(@as(usize, 1), depth),
        );

        const perturb = if (novelty >= 0.5) self.config.processing_limit_high else self.config.processing_limit_low;
        const meta_limit = @max(@as(usize, 1), perturb / 2);

        self.reasoning_orchestrator.setProcessingLimits(
            @max(@as(usize, 1), perturb),
            @max(@as(usize, 1), perturb),
            meta_limit,
        );
    }

    pub fn process(self: *Self, input: CapabilityInput) !f64 {
        const resolved_domain = self.classifyTask(input);

        self.social_model.update(resolved_domain, input.features);
        const social = self.social_model.snapshot();

        const scores = self.scoreNoveltyAndTransferability(input, resolved_domain);

        self.adjustReasoningPolicy(scores.novelty, scores.transferability, resolved_domain, social);

        const novelty_cycles = @as(usize, @intFromFloat(std.math.round(scores.novelty * @as(f64, @floatFromInt(self.config.max_cycles_novelty_bonus)))));
        const urgency_cycles = @as(usize, @intFromFloat(std.math.round(std.math.clamp(input.features.urgency, 0.0, 1.0) * @as(f64, @floatFromInt(self.config.max_cycles_urgency_bonus)))));
        const emotional_cycles = @as(usize, @intFromFloat(std.math.round(std.math.clamp(input.features.emotional_load, 0.0, 1.0) * @as(f64, @floatFromInt(self.config.max_cycles_emotional_bonus)))));
        const depth_cycles = @min(social.expected_response_depth, self.config.max_cycles_depth_bonus);

        var max_cycles = self.config.max_cycles_base;
        max_cycles = saturatingAdd(max_cycles, novelty_cycles);
        max_cycles = saturatingAdd(max_cycles, urgency_cycles);
        max_cycles = saturatingAdd(max_cycles, emotional_cycles);
        max_cycles = saturatingAdd(max_cycles, depth_cycles);
        max_cycles = @min(max_cycles, self.config.max_cycles_cap);
        max_cycles = @max(@as(usize, 1), max_cycles);

        const final_energy = try self.reasoning_orchestrator.runHierarchicalReasoning(max_cycles);
        const safe_energy = @max(0.0, final_energy);
        const success = if (safe_energy <= self.config.success_energy_perfect_threshold) 1.0 else std.math.exp(-safe_energy);

        try self.onlineConsolidate(.{
            .task_hash = input.task_id_hash,
            .domain = resolved_domain,
            .features = input.features,
            .novelty_score = scores.novelty,
            .success_rate = std.math.clamp(success, 0.0, 1.0),
            .convergence_energy = safe_energy,
            .cycles_taken = max_cycles,
            .timestamp = input.timestamp,
        });

        return final_energy;
    }

    fn onlineConsolidate(self: *Self, summary: ExperienceSummary) !void {
        try self.experience_buffer.addExperience(summary);
    }

    fn saturatingAdd(a: usize, b: usize) usize {
        return a +| b;
    }
};
```

Az alábbi egyfájlos Zig implementáció a jelenlegi `AdaptiveCapabilityLayer` szerkezetére épít, mert a mostani fájl már tartalmaz task-osztályozást, social state-et, experience buffer-t, novelty/transfer scoringot és online konszolidációt, így ezt bővítem a kért többfeladatos, adaptív, önjavító és empatikus capability-réteggé.[1]

