pub const SocialInferenceModel = struct {
    mutex: std.Thread.Mutex,
    intent_clarity: f64,
    urgency_level: f64,
    frustration_index: f64,
    cognitive_load_estimate: f64,
    mental_model_stability: f64,
    empathy_confidence: f64,
    requires_empathy: bool,
    expected_response_depth: usize,
    config: SocialConfig,

    pub fn init(config: SocialConfig) SocialInferenceModel {
        const validated = config.validated();
        return .{
            .mutex = .{},
            .intent_clarity = 0.5,
            .urgency_level = 0.5,
            .frustration_index = 0.0,
            .cognitive_load_estimate = 0.5,
            .mental_model_stability = 0.5,
            .empathy_confidence = 0.0,
            .requires_empathy = false,
            .expected_response_depth = validated.depth_min,
            .config = validated,
        };
    }

    pub fn update(self: *SocialInferenceModel, intent_score: f64, latency_ms: f64, domain: TaskDomain, features: TaskFeatures) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        const intent_signal = std.math.clamp((intent_score * 0.55) + ((1.0 - features.ambiguity) * 0.45), 0.0, 1.0);
        self.intent_clarity = std.math.clamp((self.intent_clarity * self.config.intent_decay) + (intent_signal * (1.0 - self.config.intent_decay)), 0.0, 1.0);

        self.urgency_level = std.math.clamp((self.urgency_level * 0.75) + (features.urgency * 0.25), 0.0, 1.0);
        self.cognitive_load_estimate = std.math.clamp((features.complexity * 0.40) + (features.ambiguity * 0.25) + (features.breadth * 0.20) + (features.temporal_pressure * 0.15), 0.0, 1.0);

        const latency_pressure = if (latency_ms >= self.config.high_latency_ms) 1.0 else if (latency_ms <= self.config.low_latency_ms) 0.0 else (latency_ms - self.config.low_latency_ms) / (self.config.high_latency_ms - self.config.low_latency_ms);
        const frustration_signal = std.math.clamp(
            (features.urgency * self.config.frustration_urgency_scale) +
                (features.emotional_load * self.config.frustration_emotional_scale) +
                (latency_pressure * self.config.frustration_latency_scale),
            0.0,
            1.0,
        );
        self.frustration_index = std.math.clamp((self.frustration_index * self.config.frustration_decay) + frustration_signal, 0.0, 1.0);

        const mental_model_signal = std.math.clamp((self.intent_clarity * 0.55) + ((1.0 - features.ambiguity) * 0.25) + ((1.0 - features.novelty_signal) * 0.20), 0.0, 1.0);
        self.mental_model_stability = std.math.clamp((self.mental_model_stability * self.config.mental_model_decay) + (mental_model_signal * (1.0 - self.config.mental_model_decay)), 0.0, 1.0);

        self.requires_empathy = domain == .social or features.emotional_load >= self.config.empathy_threshold or self.frustration_index >= 0.55 or features.social_density >= 0.60;

        self.empathy_confidence = std.math.clamp(
            (features.emotional_load * 0.35) +
                (features.social_density * 0.25) +
                (self.frustration_index * 0.20) +
                ((if (self.requires_empathy) 1.0 else 0.0) * 0.20),
            0.0,
            1.0,
        );

        const depth_signal = std.math.clamp(
            (self.cognitive_load_estimate * 0.35) +
                (self.frustration_index * 0.15) +
                (features.breadth * 0.15) +
                (features.novelty_signal * 0.10) +
                ((if (self.requires_empathy) 1.0 else 0.0) * 0.25),
            0.0,
            1.0,
        );
        const depth_span = self.config.depth_max - self.config.depth_min;
        const computed_depth = self.config.depth_min + @as(usize, @intFromFloat(std.math.round(depth_signal * @as(f64, @floatFromInt(depth_span)))));
        self.expected_response_depth = std.math.clamp(computed_depth, self.config.depth_min, self.config.depth_max);
    }

    pub fn snapshot(self: *SocialInferenceModel) SocialSnapshot {
        self.mutex.lock();
        defer self.mutex.unlock();
        return .{
            .intent_clarity = self.intent_clarity,
            .urgency_level = self.urgency_level,
            .frustration_index = self.frustration_index,
            .cognitive_load_estimate = self.cognitive_load_estimate,
            .mental_model_stability = self.mental_model_stability,
            .empathy_confidence = self.empathy_confidence,
            .requires_empathy = self.requires_empathy,
            .expected_response_depth = self.expected_response_depth,
        };
    }
};

const DomainBucket = struct {
    indices: []usize,
    len: usize,

    fn init(allocator: Allocator, capacity: usize) !DomainBucket {
        return .{
            .indices = try allocator.alloc(usize, capacity),
            .len = 0,
        };
    }

    fn deinit(self: *DomainBucket, allocator: Allocator) void {
        allocator.free(self.indices);
        self.indices = &[_]usize{};
        self.len = 0;
    }

    fn add(self: *DomainBucket, index: usize) !void {
        if (self.len >= self.indices.len) return error.DomainBucketFull;
        self.indices[self.len] = index;
        self.len += 1;
    }

    fn addAssumeCapacity(self: *DomainBucket, index: usize) void {
        self.indices[self.len] = index;
        self.len += 1;
    }

    fn remove(self: *DomainBucket, index: usize) bool {
        var i: usize = 0;
        while (i < self.len) : (i += 1) {
            if (self.indices[i] == index) {
                self.len -= 1;
                self.indices[i] = self.indices[self.len];
                return true;
            }
        }
        return false;
    }
};

pub const ExperienceBuffer = struct {
    allocator: Allocator,
    slots: []ExperienceSummary,
    active: []bool,
    len: usize,
    next_evict: usize,
    capacity: usize,
    exact_index: AutoHashMap(u64, usize),
    domain_buckets: [TaskDomainCount]DomainBucket,
    mutex: std.Thread.Mutex,

    pub fn init(allocator: Allocator, capacity: usize) !ExperienceBuffer {
        if (capacity == 0) return error.InvalidCapacity;

        var exact_index = AutoHashMap(u64, usize).init(allocator);
        errdefer exact_index.deinit();
        try exact_index.ensureTotalCapacity(capacity);

        var domain_buckets: [TaskDomainCount]DomainBucket = undefined;
        var initialized_buckets: usize = 0;
        errdefer {
            var i: usize = 0;
            while (i < initialized_buckets) : (i += 1) {
                domain_buckets[i].deinit(allocator);
            }
        }

        var i: usize = 0;
        while (i < TaskDomainCount) : (i += 1) {
            domain_buckets[i] = try DomainBucket.init(allocator, capacity);
            initialized_buckets += 1;
        }

        const slots = try allocator.alloc(ExperienceSummary, capacity);
        errdefer allocator.free(slots);

        const active = try allocator.alloc(bool, capacity);
        errdefer allocator.free(active);
        @memset(active, false);

        return .{
            .allocator = allocator,
            .slots = slots,
            .active = active,
            .len = 0,
            .next_evict = 0,
            .capacity = capacity,
            .exact_index = exact_index,
            .domain_buckets = domain_buckets,
            .mutex = .{},
        };
    }

    pub fn deinit(self: *ExperienceBuffer) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        self.exact_index.deinit();

        var i: usize = 0;
        while (i < TaskDomainCount) : (i += 1) {
            self.domain_buckets[i].deinit(self.allocator);
        }

        self.allocator.free(self.active);
        self.allocator.free(self.slots);

        self.active = &[_]bool{};
        self.slots = &[_]ExperienceSummary{};
        self.len = 0;
        self.next_evict = 0;
        self.capacity = 0;
    }

    pub fn count(self: *ExperienceBuffer) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.len;
    }

    pub fn addExperience(self: *ExperienceBuffer, exp: ExperienceSummary) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.exact_index.get(exp.task_hash)) |existing_index| {
            const old_domain = self.slots[existing_index].domain;
            self.slots[existing_index] = exp;
            if (old_domain != exp.domain) {
                _ = self.domain_buckets[@intFromEnum(old_domain)].remove(existing_index);
                try self.domain_buckets[@intFromEnum(exp.domain)].add(existing_index);
            }
            self.active[existing_index] = true;
            return;
        }

        if (self.len < self.capacity) {
            const insert_index = self.len;
            try self.exact_index.put(exp.task_hash, insert_index);
            errdefer _ = self.exact_index.remove(exp.task_hash);

            self.slots[insert_index] = exp;
            self.active[insert_index] = true;
            self.len += 1;
            errdefer {
                self.active[insert_index] = false;
                self.len -= 1;
            }

            try self.domain_buckets[@intFromEnum(exp.domain)].add(insert_index);
            return;
        }

        const replace_index = self.next_evict;
        const had_old = self.active[replace_index];
        const old_exp = if (had_old) self.slots[replace_index] else undefined;

        if (had_old) {
            _ = self.exact_index.remove(old_exp.task_hash);
            _ = self.domain_buckets[@intFromEnum(old_exp.domain)].remove(replace_index);
        }

        errdefer {
            if (had_old) {
                self.slots[replace_index] = old_exp;
                self.active[replace_index] = true;
                self.exact_index.put(old_exp.task_hash, replace_index) catch unreachable;
                self.domain_buckets[@intFromEnum(old_exp.domain)].addAssumeCapacity(replace_index);
            } else {
                self.active[replace_index] = false;
            }
        }

        try self.exact_index.put(exp.task_hash, replace_index);
        self.slots[replace_index] = exp;
        self.active[replace_index] = true;
        try self.domain_buckets[@intFromEnum(exp.domain)].add(replace_index);

        self.next_evict = (replace_index + 1) % self.capacity;
    }

    pub fn retrieveRelevant(self: *ExperienceBuffer, input: CapabilityInput, resolved_domain: TaskDomain, feature_scales: FeatureScales, age_penalty_scale: f64) ?ExperienceSummary {
        const now = input.timestamp;

        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.exact_index.get(input.task_hash)) |exact_index| {
            if (self.active[exact_index]) {
                return self.slots[exact_index];
            }
        }

        var best_match: ?ExperienceSummary = null;
        var min_distance = std.math.floatMax(f64);

        if (resolved_domain == .unknown) {
            var i: usize = 0;
            while (i < self.len) : (i += 1) {
                if (!self.active[i]) continue;
                const exp = self.slots[i];
                const distance = featureDistance(exp.features, input.features, feature_scales) + agePenalty(now, exp.timestamp, age_penalty_scale);
                if (distance < min_distance) {
                    min_distance = distance;
                    best_match = exp;
                }
            }
            return best_match;
        }

        const bucket = self.domain_buckets[@intFromEnum(resolved_domain)];
        var i: usize = 0;
        while (i < bucket.len) : (i += 1) {
            const slot_index = bucket.indices[i];
            if (!self.active[slot_index]) continue;
            const exp = self.slots[slot_index];
            const distance = featureDistance(exp.features, input.features, feature_scales) + agePenalty(now, exp.timestamp, age_penalty_scale);
            if (distance < min_distance) {
                min_distance = distance;
                best_match = exp;
            }
        }

        return best_match;
    }

    fn featureDistance(a: TaskFeatures, b: TaskFeatures, s: FeatureScales) f64 {
        const dc = (a.complexity - b.complexity) / s.complexity;
        const da = (a.ambiguity - b.ambiguity) / s.ambiguity;
        const du = (a.urgency - b.urgency) / s.urgency;
        const de = (a.emotional_load - b.emotional_load) / s.emotional_load;
        const dn = (a.novelty_signal - b.novelty_signal) / s.novelty_signal;
        const ds = (a.social_density - b.social_density) / s.social_density;
        const db = (a.breadth - b.breadth) / s.breadth;
        const dt = (a.temporal_pressure - b.temporal_pressure) / s.temporal_pressure;
        const sum = (dc * dc) + (da * da) + (du * du) + (de * de) + (dn * dn) + (ds * ds) + (db * db) + (dt * dt);
        return std.math.clamp(std.math.sqrt(sum / 8.0), 0.0, 1.0);
    }

    fn agePenalty(now: i64, then: i64, scale: f64) f64 {
        const delta_ns = now - then;
        if (delta_ns <= 0 or scale <= 0.0) return 0.0;
        const delta_s = @as(f64, @floatFromInt(delta_ns)) / 1_000_000_000.0;
        return @max(0.0, delta_s * scale);
    }
};

pub const PolicyDecision = struct {
    strategy: StrategyMode,
    fast_steps: usize,
    slow_steps: usize,
    reasoning_depth: usize,
    max_cycles: usize,
    expected_energy: f64,
};

pub const ProcessResult = struct {
    domain: TaskDomain,
    strategy: StrategyMode,
    novelty: f64,
    transferability: f64,
    social: SocialSnapshot,
    policy: PolicyDecision,
    expected_energy: f64,
};

pub const AdaptiveCapabilityLayer = struct {
    graph: *SelfSimilarRelationalGraph,
    reasoning_orchestrator: *ReasoningOrchestrator,
    experience_buffer: ExperienceBuffer,
    social_model: SocialInferenceModel,
    config: AdaptiveCapabilityConfig,
    domain_weights: [TaskDomainCount]f64,
    strategy_weights: [StrategyModeCount]f64,

    const Self = @This();

    pub fn init(allocator: Allocator, graph: *SelfSimilarRelationalGraph, reasoning_orch: *ReasoningOrchestrator) !Self {
        return Self.initWithConfig(allocator, graph, reasoning_orch, .{});
    }

    pub fn initWithConfig(allocator: Allocator, graph: *SelfSimilarRelationalGraph, reasoning_orch: *ReasoningOrchestrator, config: AdaptiveCapabilityConfig) !Self {
        const validated = config.validated();
        return .{
            .graph = graph,
            .reasoning_orchestrator = reasoning_orch,
            .experience_buffer = try ExperienceBuffer.init(allocator, validated.experience_capacity),
            .social_model = SocialInferenceModel.init(validated.social),
            .config = validated,
            .domain_weights = [_]f64{1.0} ** TaskDomainCount,
            .strategy_weights = [_]f64{1.0} ** StrategyModeCount,
        };
    }

    pub fn deinit(self: *Self) void {
        self.experience_buffer.deinit();
    }

    pub fn classifyTask(self: *Self, input: CapabilityInput) TaskDomain {
        if (input.domain_hint != .unknown) return input.domain_hint;

        const features = input.features.normalized();
        const label = normalizeLabel(input.domain_label, input.domain_len);

        var scores = [_]f64{0.0} ** TaskDomainCount;

        if (std.mem.eql(u8, label, "math") or std.mem.eql(u8, label, "logic") or std.mem.eql(u8, label, "analysis")) {
            scores[@intFromEnum(TaskDomain.analytical)] += 1.0;
        }
        if (std.mem.eql(u8, label, "creative") or std.mem.eql(u8, label, "art") or std.mem.eql(u8, label, "generation") or std.mem.eql(u8, label, "writing")) {
            scores[@intFromEnum(TaskDomain.creative)] += 1.0;
        }
        if (std.mem.eql(u8, label, "chat") or std.mem.eql(u8, label, "dialogue") or std.mem.eql(u8, label, "conversation")) {
            scores[@intFromEnum(TaskDomain.interactive)] += 1.0;
        }
        if (std.mem.eql(u8, label, "social") or std.mem.eql(u8, label, "empathy") or std.mem.eql(u8, label, "support")) {
            scores[@intFromEnum(TaskDomain.social)] += 1.0;
        }
        if (std.mem.eql(u8, label, "plan") or std.mem.eql(u8, label, "planning") or std.mem.eql(u8, label, "strategy")) {
            scores[@intFromEnum(TaskDomain.planning)] += 1.0;
        }
        if (std.mem.eql(u8, label, "spatial") or std.mem.eql(u8, label, "vision") or std.mem.eql(u8, label, "geometry")) {
            scores[@intFromEnum(TaskDomain.spatial)] += 1.0;
        }
        if (std.mem.eql(u8, label, "learn") or std.mem.eql(u8, label, "learning") or std.mem.eql(u8, label, "adapt")) {
            scores[@intFromEnum(TaskDomain.learning)] += 1.0;
        }
        if (std.mem.eql(u8, label, "error") or std.mem.eql(u8, label, "recover") or std.mem.eql(u8, label, "retry")) {
            scores[@intFromEnum(TaskDomain.recovery)] += 1.0;
        }

        if (features.emotional_load >= self.config.social_emotional_threshold or features.social_density >= self.config.social_density_threshold) {
            scores[@intFromEnum(TaskDomain.social)] += 0.95;
        }
        if (features.complexity >= self.config.analytical_complexity_threshold and features.ambiguity <= self.config.analytical_ambiguity_threshold) {
            scores[@intFromEnum(TaskDomain.analytical)] += 0.90;
        }
        if (features.ambiguity >= self.config.creative_ambiguity_threshold or features.breadth >= self.config.creative_breadth_threshold) {
            scores[@intFromEnum(TaskDomain.creative)] += 0.80;
        }
        if (features.urgency >= self.config.interactive_urgency_threshold or features.temporal_pressure >= 0.65) {
            scores[@intFromEnum(TaskDomain.interactive)] += 0.75;
        }
        if (features.complexity >= self.config.planning_complexity_threshold and features.breadth >= self.config.planning_breadth_threshold) {
            scores[@intFromEnum(TaskDomain.planning)] += 0.80;
        }
        if (features.breadth >= self.config.spatial_breadth_threshold and features.ambiguity < 0.50) {
            scores[@intFromEnum(TaskDomain.spatial)] += 0.60;
        }
        if (features.novelty_signal >= self.config.learning_novelty_threshold) {
            scores[@intFromEnum(TaskDomain.learning)] += 0.85;
        }
        if (features.urgency >= self.config.recovery_urgency_threshold and features.emotional_load >= 0.35) {
            scores[@intFromEnum(TaskDomain.recovery)] += 0.65;
        }

        var best_domain: TaskDomain = .unknown;
        var best_score: f64 = -1.0;

        for (0..TaskDomainCount) |i| {
            const weighted_score = scores[i] * self.domain_weights[i];
            if (weighted_score > best_score) {
                best_score = weighted_score;
                best_domain = @enumFromInt(i);
            }
        }

        if (best_score <= 0.0) return .unknown;
        return best_domain;
    }

    pub fn scoreNoveltyAndTransferability(self: *Self, input: CapabilityInput, resolved_domain: TaskDomain) struct { novelty: f64, transferability: f64, prior: ?ExperienceSummary } {
        const features = input.features.normalized();
        const prior = self.experience_buffer.retrieveRelevant(.{
            .task_hash = input.task_hash,
            .domain_hint = input.domain_hint,
            .domain_label = input.domain_label,
            .domain_len = input.domain_len,
            .features = features,
            .user_intent_score = input.user_intent_score,
            .latency_ms = input.latency_ms,
            .timestamp = input.timestamp,
        }, resolved_domain, self.config.feature_scales, self.config.policy.age_penalty_scale);

        if (prior == null) {
            return .{
                .novelty = std.math.clamp((features.novelty_signal * 0.55) + (features.ambiguity * 0.20) + (features.breadth * 0.15) + (features.temporal_pressure * 0.10), 0.0, 1.0),
                .transferability = 0.0,
                .prior = null,
            };
        }

        const exp = prior.?;
        const distance = ExperienceBuffer.featureDistance(exp.features, features, self.config.feature_scales);
        const age_component = ExperienceBuffer.agePenalty(input.timestamp, exp.timestamp, self.config.policy.age_penalty_scale);
        const novelty = std.math.clamp((distance * 0.70) + (features.novelty_signal * 0.20) + age_component, 0.0, 1.0);

        const success_component = std.math.clamp(exp.success_rate, 0.0, 1.0);
        const energy_component = 1.0 - std.math.clamp(exp.convergence_energy, 0.0, 1.0);
        const domain_alignment = if (exp.domain == resolved_domain) 1.0 else 0.60;
        const transferability = std.math.clamp((1.0 - novelty) * ((success_component * 0.55) + (energy_component * 0.25) + (domain_alignment * 0.20)), 0.0, 1.0);

        return .{
            .novelty = novelty,
            .transferability = transferability,
            .prior = exp,
        };
    }

    pub fn selectStrategy(self: *Self, domain: TaskDomain, novelty: f64, transferability: f64, social: SocialSnapshot) StrategyMode {
        var scores = [_]f64{0.0} ** StrategyModeCount;

        scores[@intFromEnum(StrategyMode.exploit)] += (transferability * 0.80) + ((1.0 - novelty) * 0.20);
        scores[@intFromEnum(StrategyMode.explore)] += (novelty * 0.80) + (1.0 - transferability) * 0.20;
        scores[@intFromEnum(StrategyMode.empathic)] += (social.empathy_confidence * 0.65) + ((if (social.requires_empathy) 1.0 else 0.0) * 0.35);
        scores[@intFromEnum(StrategyMode.deliberate)] += (social.cognitive_load_estimate * 0.35) + (social.expected_response_depth_f64() * 0.20) + (domainDeliberationBias(domain) * 0.45);
        scores[@intFromEnum(StrategyMode.reactive)] += (social.urgency_level * 0.50) + (social.frustration_index * 0.25) + (domainReactiveBias(domain) * 0.25);

        var best: StrategyMode = .exploit;
        var best_score: f64 = -1.0;

        for (0..StrategyModeCount) |i| {
            const weighted = scores[i] * self.strategy_weights[i];
            if (weighted > best_score) {
                best_score = weighted;
                best = @enumFromInt(i);
            }
        }

        return best;
    }

    pub fn adjustReasoningPolicy(self: *Self, domain: TaskDomain, novelty: f64, transferability: f64, social: SocialSnapshot, strategy: StrategyMode, features: TaskFeatures) PolicyDecision {
        var fast = self.config.policy.base_fast;
        var slow = self.config.policy.base_slow;
        var depth = self.config.policy.base_depth;

        if (novelty >= 0.70) {
            fast = saturatingAdd(fast, self.config.policy.high_novel_fast_bonus);
            slow = saturatingAdd(slow, self.config.policy.high_novel_slow_bonus);
            depth = saturatingAdd(depth, self.config.policy.high_novel_depth_bonus);
        }

        if (transferability >= 0.75) {
            fast = saturatingSub(fast, self.config.policy.high_transfer_fast_reduction);
            slow = saturatingSub(slow, self.config.policy.high_transfer_slow_reduction);
        }

        switch (domain) {
            .analytical => {
                fast = saturatingAdd(fast, self.config.policy.analytical_fast_bonus);
            },
            .creative => {
                slow = saturatingAdd(slow, self.config.policy.creative_slow_bonus);
                depth = saturatingAdd(depth, self.config.policy.creative_depth_bonus);
            },
            .interactive => {
                fast = saturatingAdd(fast, self.config.policy.interactive_fast_bonus);
            },
            .social => {
                slow = saturatingAdd(slow, self.config.policy.social_slow_bonus);
                depth = @max(depth, social.expected_response_depth);
            },
            .planning => {
                depth = saturatingAdd(depth, self.config.policy.planning_depth_bonus);
            },
            .spatial => {
                depth = @max(depth, 4);
            },
            .learning => {
                depth = saturatingAdd(depth, self.config.policy.learning_depth_bonus);
            },
            .recovery => {
                slow = saturatingAdd(slow, self.config.policy.recovery_slow_bonus);
                depth = saturatingAdd(depth, self.config.policy.recovery_depth_bonus);
            },
            .unknown => {},
        }

        switch (strategy) {
            .exploit => {
                fast = saturatingAdd(fast, 6);
                slow = saturatingSub(slow, 1);
            },
            .explore => {
                slow = saturatingAdd(slow, 6);
                depth = saturatingAdd(depth, 2);
            },
            .empathic => {
                slow = saturatingAdd(slow, 4);
                depth = @max(depth, social.expected_response_depth);
            },
            .deliberate => {
                slow = saturatingAdd(slow, 5);
                depth = saturatingAdd(depth, 2);
            },
            .reactive => {
                fast = saturatingAdd(fast, 10);
            },
        }

        if (social.requires_empathy) {
            depth = @max(depth, social.expected_response_depth);
        }

        if (features.breadth >= 0.70) {
            depth = saturatingAdd(depth, 1);
        }

        fast = std.math.clamp(fast, @as(usize, 1), self.config.policy.max_fast);
        slow = std.math.clamp(slow, @as(usize, 1), self.config.policy.max_slow);
        depth = std.math.clamp(depth, @as(usize, 1), self.config.policy.max_depth);

        self.reasoning_orchestrator.setParameters(fast, slow, depth);

        const processing_limit = switch (strategy) {
            .exploit => self.config.policy.exploit_processing_limit,
            .explore => self.config.policy.explore_processing_limit,
            .empathic => self.config.policy.deliberate_processing_limit,
            .deliberate => self.config.policy.deliberate_processing_limit,
            .reactive => self.config.policy.explore_processing_limit,
        };

        const meta_limit = @max(@as(usize, 1), processing_limit / 2);

        self.reasoning_orchestrator.setProcessingLimits(
            processing_limit,
            processing_limit,
            meta_limit,
        );

        var max_cycles = self.config.policy.max_cycles_base;
        max_cycles = saturatingAdd(max_cycles, @as(usize, @intFromFloat(std.math.round(novelty * @as(f64, @floatFromInt(self.config.policy.max_cycles_novelty_bonus))))));
        max_cycles = saturatingAdd(max_cycles, @as(usize, @intFromFloat(std.math.round(features.urgency * @as(f64, @floatFromInt(self.config.policy.max_cycles_urgency_bonus))))));
        max_cycles = saturatingAdd(max_cycles, @as(usize, @intFromFloat(std.math.round(features.emotional_load * @as(f64, @floatFromInt(self.config.policy.max_cycles_emotional_bonus))))));
        max_cycles = saturatingAdd(max_cycles, @as(usize, @intFromFloat(std.math.round(features.breadth * @as(f64, @floatFromInt(self.config.policy.max_cycles_breadth_bonus))))));
        max_cycles = saturatingAdd(max_cycles, @min(depth, self.config.policy.max_cycles_depth_bonus));
        max_cycles = std.math.clamp(max_cycles, @as(usize, 1), self.config.policy.max_cycles_cap);

        const expected_energy = std.math.clamp(
            (0.18 * @as(f64, @floatFromInt(slow))) +
                (0.03 * @as(f64, @floatFromInt(depth))) +
                (0.12 * novelty) -
                (0.08 * transferability) +
                (0.05 * features.breadth) +
                (0.05 * features.temporal_pressure),
            0.0,
            1024.0,
        );

        return .{
            .strategy = strategy,
            .fast_steps = fast,
            .slow_steps = slow,
            .reasoning_depth = depth,
            .max_cycles = max_cycles,
            .expected_energy = expected_energy,
        };
    }

    pub fn process(self: *Self, input: CapabilityInput) !ProcessResult {
        const normalized_input = CapabilityInput{
            .task_hash = input.task_hash,
            .domain_hint = input.domain_hint,
            .domain_label = input.domain_label,
            .domain_len = @min(input.domain_len, input.domain_label.len),
            .features = input.features.normalized(),
            .user_intent_score = std.math.clamp(input.user_intent_score, 0.0, 1.0),
            .latency_ms = @max(0.0, input.latency_ms),
            .timestamp = input.timestamp,
        };

        const resolved_domain = self.classifyTask(normalized_input);

        self.social_model.update(
            normalized_input.user_intent_score,
            normalized_input.latency_ms,
            resolved_domain,
            normalized_input.features,
        );

        const social = self.social_model.snapshot();
        const novelty_transfer = self.scoreNoveltyAndTransferability(normalized_input, resolved_domain);
        const strategy = self.selectStrategy(resolved_domain, novelty_transfer.novelty, novelty_transfer.transferability, social);
        const policy = self.adjustReasoningPolicy(
            resolved_domain,
            novelty_transfer.novelty,
            novelty_transfer.transferability,
            social,
            strategy,
            normalized_input.features,
        );

        const final_energy = try self.reasoning_orchestrator.runHierarchicalReasoning(policy.max_cycles);
        const safe_energy = @max(0.0, final_energy);
        const success_rate = if (safe_energy <= self.config.policy.success_energy_perfect_threshold) 1.0 else std.math.clamp(std.math.exp(-safe_energy), 0.0, 1.0);

        try self.onlineConsolidate(.{
            .task_hash = normalized_input.task_hash,
            .domain = resolved_domain,
            .strategy = strategy,
            .features = normalized_input.features,
            .novelty_score = novelty_transfer.novelty,
            .transferability_score = novelty_transfer.transferability,
            .success_rate = success_rate,
            .convergence_energy = safe_energy,
            .reasoning_depth_used = policy.reasoning_depth,
            .fast_inner_steps_used = policy.fast_steps,
            .slow_outer_steps_used = policy.slow_steps,
            .cycles_taken = policy.max_cycles,
            .timestamp = normalized_input.timestamp,
        });

        return .{
            .domain = resolved_domain,
            .strategy = strategy,
            .novelty = novelty_transfer.novelty,
            .transferability = novelty_transfer.transferability,
            .social = social,
            .policy = policy,
            .expected_energy = safe_energy,
        };
    }

    pub fn onlineConsolidate(self: *Self, summary: ExperienceSummary) !void {
        try self.experience_buffer.addExperience(summary);

        const success_delta = summary.success_rate - 0.5;
        const domain_idx = @intFromEnum(summary.domain);
        const strategy_idx = @intFromEnum(summary.strategy);

        self.domain_weights[domain_idx] = std.math.clamp(
            self.domain_weights[domain_idx] + (success_delta * self.config.policy.domain_learning_rate),
            0.25,
            4.0,
        );

        self.strategy_weights[strategy_idx] = std.math.clamp(
            self.strategy_weights[strategy_idx] + (success_delta * self.config.policy.strategy_learning_rate),
            0.25,
            4.0,
        );
    }

    fn normalizeLabel(buffer: [64]u8, len: usize) []const u8 {
        var tmp = buffer;
        var i: usize = 0;
        const n = @min(len, tmp.len);
        while (i < n) : (i += 1) {
            tmp[i] = std.ascii.toLower(tmp[i]);
        }
        return std.mem.trim(u8, tmp[0..n], " \t\r\n");
    }

    fn domainDeliberationBias(domain: TaskDomain) f64 {
        return switch (domain) {
            .analytical => 1.0,
            .planning => 1.0,
            .learning => 0.9,
            .creative => 0.6,
            .social => 0.5,
            .spatial => 0.5,
            .interactive => 0.3,
            .recovery => 0.7,
            .unknown => 0.4,
        };
    }

    fn domainReactiveBias(domain: TaskDomain) f64 {
        return switch (domain) {
            .interactive => 1.0,
            .recovery => 0.95,
            .social => 0.7,
            .creative => 0.4,
            .analytical => 0.3,
            .planning => 0.2,
            .spatial => 0.3,
            .learning => 0.2,
            .unknown => 0.5,
        };
    }

    fn saturatingAdd(a: usize, b: usize) usize {
        return a +| b;
    }

    fn saturatingSub(a: usize, b: usize) usize {
        return a -| b;
    }
};

fn expected_response_depth_f64(snapshot: SocialSnapshot) f64 {
    return @as(f64, @floatFromInt(snapshot.expected_response_depth));
}

pub fn expected_response_depth_f64(self: SocialSnapshot) f64 {
    return @as(f64, @floatFromInt(self.expected_response_depth));
}
